package com.collabcase.agent;
import java.time.Duration;import java.util.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Value;import com.collabcase.teamai.connector.AiJobQueue;import org.springframework.http.client.JdkClientHttpRequestFactory;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import tools.jackson.databind.JsonNode;
@Component public class ConfiguredAgentProvider implements AgentProvider{
 private final String provider,model,key;private final RestClient client;private final ObjectProvider<AiJobQueue> queues;
 public ConfiguredAgentProvider(@Value("${agent.provider:ollama}")String provider,@Value("${agent.ollama.base-url:http://localhost:11434}")String ollamaUrl,@Value("${agent.ollama.model:qwen3:1.7b}")String ollamaModel,@Value("${agent.groq.base-url:https://api.groq.com/openai/v1}")String groqUrl,@Value("${agent.groq.model:openai/gpt-oss-20b}")String groqModel,@Value("${agent.groq.api-key:}")String key,@Value("${agent.timeout-seconds:90}")long timeout,ObjectProvider<AiJobQueue> queues){this.queues=queues;this.provider=provider.toLowerCase(Locale.ROOT);this.model="groq".equals(this.provider)?groqModel:ollamaModel;this.key=key;var factory=new JdkClientHttpRequestFactory();factory.setReadTimeout(Duration.ofSeconds(timeout));this.client=RestClient.builder().baseUrl("groq".equals(this.provider)?groqUrl:ollamaUrl).requestFactory(factory).build();}
 public String generate(String system,String user,String schema){if("conector".equals(provider)){try{return queue().runBlocking(List.of(Map.of("role","system","content",system),Map.of("role","user","content",user)),tools.jackson.databind.json.JsonMapper.builder().build().readValue(schema,Map.class));}catch(Exception e){throw new AgentUnavailableException(e.getMessage()==null?"IA desconectada":e.getMessage(),e);}}try{JsonNode response;if("groq".equals(provider)){if(key.isBlank())throw new IllegalStateException("Missing agent cloud key");response=client.post().uri("/chat/completions").header("Authorization","Bearer "+key).body(Map.of("model",model,"temperature",0,"messages",List.of(Map.of("role","system","content",system),Map.of("role","user","content",user)),"response_format",Map.of("type","json_object"))).retrieve().body(JsonNode.class);return response.path("choices").path(0).path("message").path("content").asText();}response=client.post().uri("/api/chat").body(Map.of("model",model,"stream",false,"format",tools.jackson.databind.json.JsonMapper.builder().build().readValue(schema,Map.class),"options",Map.of("temperature",0),"messages",List.of(Map.of("role","system","content",system),Map.of("role","user","content",user)))).retrieve().body(JsonNode.class);return response.path("message").path("content").asText();}catch(Exception e){throw new AgentUnavailableException("groq".equals(provider)?"El agente online no está disponible temporalmente.":"El agente local no está disponible.",e);}}
 private AiJobQueue queue(){AiJobQueue q=queues.getIfAvailable();if(q==null)throw new IllegalStateException("IA desconectada");return q;}
 public String name(){return provider;}public boolean available(){if("conector".equals(provider)){AiJobQueue q=queues.getIfAvailable();return q!=null&&q.connected();}try{if("groq".equals(provider))return !key.isBlank();client.get().uri("/api/tags").retrieve().toBodilessEntity();return true;}catch(Exception e){return false;}}
}
